export default {"id":"sounddesign-level-6","number":6,"title":"Voices Signal Flow","skillBand":"Textbook","duration":"From the course textbook","summary":"- Differentiate Monophonic and Polyphonic voice allocation modes and configure Voice Priority (Last, Low, High). - Configure Polyphonic Voice Counts and evaluate voice-stealing algorithms during dense chord passages.","modules":[{"id":"sounddesign-m-6-1-1","code":"6.1","title":"Mono, Poly, Unison, and Glide","blurb":"- Differentiate Monophonic and Polyphonic voice allocation modes and configure Voice Priority (Last, Low, High). - Configure Polyphonic Voice Counts and evaluate voice-stealing algorithms during dense chord passages.","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"sounddesign-l-o-16","title":"Section overview","blocks":[{"type":"step","title":"Learning Objectives","blocks":[{"type":"list","items":["Differentiate <strong>Monophonic</strong> and <strong>Polyphonic</strong> voice allocation modes and configure <strong>Voice Priority</strong> (Last, Low, High).","Configure <strong>Polyphonic Voice Counts</strong> and evaluate voice-stealing algorithms during dense chord passages.","Deploy <strong>Unison Stacks</strong> and calibrate <strong>Unison Detune</strong> and <strong>Stereo Spread</strong> to synthesize wide, chorused supersaws and thick leads.","Calibrate <strong>Portamento / Glide Time</strong> and distinguish <strong>Always Glide</strong> from <strong>Legato Auto-Glide</strong>.","Locate voice allocation, unison, and glide controls across <code>Drift</code>, <code>Analog</code>, <code>Operator</code>, <code>Vital</code>, and <code>Surge XT</code>."],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-6-1-1","title":"6.1.1 — Monophonic Mode: One Note at a Time","blocks":[{"type":"step","title":"6.1.1 — Monophonic Mode: One Note at a Time","blocks":[{"type":"prose","html":"<strong>Monophonic Mode (Mono)</strong> restricts the synthesizer to generating only a single musical pitch at any given moment. If a new key is struck while a previous key is still held, the synth does not play a two-note chord; it transitions to the new pitch according to its <strong>Voice Priority</strong> rule."},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+----------------------+----------------------------------------------------------------+\n| Voice Priority Rule  | Operational Behavior on Overlapping Keys                       |\n+----------------------+----------------------------------------------------------------+\n| **Last Note Priority**| The most recently pressed key takes priority (Modern Standard).|\n+----------------------+----------------------------------------------------------------+\n| **Low Note Priority** | The lowest physical pitch on the keyboard always takes priority|\n|                      | (Vintage Minimoog standard; preserves bass root notes).        |\n+----------------------+----------------------------------------------------------------+\n| **High Note Priority**| The highest physical pitch takes priority (Favors lead melodies)|\n+----------------------+----------------------------------------------------------------+</pre>"}]},{"type":"step","title":"Why Monophonic Mode is Mandatory for Bass:","blocks":[{"type":"list","items":["<strong>Low-End Phase Protection:</strong> Playing chords below 100 Hz creates violent phase cancellations and intermodulation distortion. Monophonic mode makes polyphonic bass clashes physically impossible.","<strong>Glide Integration:</strong> Monophonic voicing is required for portamento glides and legato slides."],"ordered":true},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Ultimate Sound Design: Mastering Sound Design</em>, Section 6.1 (Voice Allocation Modes)","<em>Sound-Design-Beginner-Knowledgebase.md</em>, §5"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-6-1-2","title":"6.1.2 — Polyphonic Mode: Voice Count and Stealing","blocks":[{"type":"step","title":"6.1.2 — Polyphonic Mode: Voice Count and Stealing","blocks":[{"type":"prose","html":"<strong>Polyphonic Mode (Poly)</strong> allows the synthesizer to sound multiple independent notes simultaneously, enabling chords and multi-voice harmonies."},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">Polyphonic Voice Pool (Max Voices = 4):\n[ Note 1 (C3) ] ===&gt; Voice Engine 1\n[ Note 2 (E3) ] ===&gt; Voice Engine 2\n[ Note 3 (G3) ] ===&gt; Voice Engine 3\n[ Note 4 (B3) ] ===&gt; Voice Engine 4\n   [ Note 5 (D4) Triggered ] ===&gt; [ VOICE STEALING OCCURS: Kills oldest voice (C3) to play D4 ]</pre>"},{"type":"list","items":["<strong>Voice Count (1 - 32 Voices):</strong> Dictates the maximum number of simultaneous notes. Each polyphonic voice duplicates the entire internal synth architecture (Oscillators, Filters, Envelopes, LFOs), multiplying CPU consumption proportionally.","<strong>Voice Stealing:</strong> When you play a 5th note on a 4-voice synth, the synth algorithm \"steals\" the oldest active voice or the quietest decaying voice to render the new note.","<strong>Sound Design Rule:</strong> Restrict pads to 6-8 voices and keys to 4-6 voices to conserve CPU and prevent long release tails from overloading the stereo bus."],"ordered":false},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Ableton Live 12 Reference Manual</em>, Chapter 23 (Analog &amp; Drift Voice Management)","<em>Sound-Design-Beginner-Knowledgebase.md</em>, §5"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-6-1-3","title":"6.1.3 — Unison Mode: Stacking Multiple Voices on One Note","blocks":[{"type":"step","title":"6.1.3 — Unison Mode: Stacking Multiple Voices on One Note","blocks":[{"type":"prose","html":"<strong>Unison Mode</strong> takes multiple internal synthesizer voices and stacks them simultaneously onto a <strong>single MIDI note</strong>."},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">Single Voice (Standard):\n[ MIDI Note C3 ] ===&gt; [ 1 Voice (Osc 1 + Filter + Amp) ] ===&gt; [ Clean, Focused Tone ]\n\n8-Voice Unison Stack:\n                      +===&gt; [ Voice 1 (Detuned -14 cents, Panned Hard Left)  ]\n                      +===&gt; [ Voice 2 (Detuned -10 cents, Panned Mid Left)   ]\n                      +===&gt; [ Voice 3 (Detuned  -5 cents, Panned Soft Left)  ]\n[ MIDI Note C3 ] ===&gt; +===&gt; [ Voice 4 (Center Pitch 0c,   Panned Center)     ] ===&gt; [ MASSIVE STEREO SUPERSAW ]\n                      +===&gt; [ Voice 5 (Detuned  +5 cents, Panned Soft Right) ]\n                      +===&gt; [ Voice 6 (Detuned +10 cents, Panned Mid Right)  ]\n                      +===&gt; [ Voice 7 (Detuned +14 cents, Panned Hard Right) ]</pre>"},{"type":"prose","html":"Instead of playing one sawtooth wave, an 8-voice unison stack generates eight individual sawtooth waves firing concurrently on every keypress."},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Ultimate Sound Design: Mastering Sound Design</em>, Section 6.2 (Unison Architecture)","<em>Sound-Design-Beginner-Knowledgebase.md</em>, §5"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-6-1-4","title":"6.1.4 — Detune in Unison: Phase Beating and Supersaws","blocks":[{"type":"step","title":"6.1.4 — Detune in Unison: Phase Beating and Supersaws","blocks":[{"type":"prose","html":"If eight unison voices were tuned to the exact same frequency, their waveforms would simply sum together into a louder version of the single wave."},{"type":"prose","html":"To create thickness, <strong>Unison Detune</strong> applies micro-pitch offsets (± 2 to ± 35 cents) symmetrically across the stacked voices."},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">Amplitude\n  ^\n  |  /\\  /\\  /\\      /\\      /\\  /\\  /\\   [Constructive Interference: Loud Peak]\n  | /  \\/  \\/  \\____/  \\____/  \\/  \\/  \\  [Destructive Interference: Phase Cancellation]\n  +-------------------------------------&gt; Time\n  |&lt;-------- Rhythmic Phase Beating Cycle --------&gt;|</pre>"}]},{"type":"step","title":"Acoustic Mechanism:","blocks":[{"type":"prose","html":"The micro-pitch frequency differences cause the waveforms to continuously drift in and out of phase with one another (constructive and destructive interference). This creates complex acoustic <strong>phase beating</strong>—the lush, chorused, massive sound signature of <strong>Supersaws</strong> and <strong>Reese Basses</strong>."},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Vital User Manual</em>, Section 2 (Unison Detuning &amp; Blend)","<em>PML Synthesis – 1 – Oscillator</em>, Chapter 4"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-6-1-5","title":"6.1.5 — Stereo Spread: Distributing Unison Across the Stereo Field","blocks":[{"type":"step","title":"6.1.5 — Stereo Spread: Distributing Unison Across the Stereo Field","blocks":[{"type":"prose","html":"In modern engines (<code>Vital</code>, <code>Surge XT</code>), Unison is paired with <strong>Stereo Spread (Pan Spread)</strong>:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[ UNISON ENGINE ]\n       |\n       +---&gt; Voice 1 &amp; 2: Panned $100\\%$ Left &amp; Right (Outer Boundary)\n       +---&gt; Voice 3 &amp; 4: Panned $60\\%$ Left &amp; Right  (Mid Field)\n       +---&gt; Voice 5 &amp; 6: Panned $25\\%$ Left &amp; Right  (Inner Field)\n       +---&gt; Voice 7 &amp; 8: Panned $0\\%$ Center         (Direct Center Core)</pre>"},{"type":"list","items":["Spreading detuned voices across the stereo field creates an ultra-wide, wall-of-sound stereo image.","<strong>Bass Precaution:</strong> High unison stereo spread on sub-bass frequencies causes severe out-of-phase cancellation when summed to mono. Always keep sub frequencies below 100 Hz focused dead-center in mono."],"ordered":false},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Vital User Manual</em>, Section 2 (Stereo Width Controls)","<em>Sound-Design-Beginner-Knowledgebase.md</em>, §5"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-6-1-6","title":"6.1.6 — Portamento / Glide: Time-Based Pitch Slides","blocks":[{"type":"step","title":"6.1.6 — Portamento / Glide: Time-Based Pitch Slides","blocks":[{"type":"prose","html":"<strong>Portamento</strong> (or <strong>Glide</strong>) creates a continuous, smooth pitch slide when transitioning from one MIDI note to the next."},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">Pitch\nD3 |              /========================= [Slide Reaches Target Note D3]\n   |             /\nC2 | ===========/                            [Initial Note C2 Played]\n   +-----------+-----------------------------&gt; Time\n               |&lt;-- Glide Time (e.g. 120 ms) --&gt;|</pre>"},{"type":"list","items":["<strong>Glide Time (1 ms - 5 s):</strong> Sets the speed of the pitch transition.","<strong>Fast Glide (30 ms - 80 ms):</strong> Adds a natural vocal / fretless bass slide between notes without dragging the tempo.","<strong>Long Glide (200 ms - 800 ms):</strong> Produces dramatic, sweeping pitch bends characteristic of 808 trap basslines and cinematic sci-fi leads."],"ordered":false},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Ultimate Sound Design: Mastering Sound Design</em>, Section 6.3 (Portamento Mechanics)","<em>Sound-Design-Beginner-Knowledgebase.md</em>, §5"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-6-1-7","title":"6.1.7 — Legato Glide vs. Always Glide","blocks":[{"type":"step","title":"6.1.7 — Legato Glide vs. Always Glide","blocks":[{"type":"prose","html":"Synthesizers feature two distinct operational modes for glide behavior:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+----------------------+----------------------------------------------------------------+\n| Glide Mode           | Operational Behavior                                           |\n+----------------------+----------------------------------------------------------------+\n| **Always Glide**     | The synth glides between EVERY note played, even if there is   |\n|                      | a complete silence/gap between consecutive keypresses.         |\n+----------------------+----------------------------------------------------------------+\n| **Legato Glide**     | The synth glides **ONLY when notes overlap** (the second key is|\n| **(Auto-Glide)**     | pressed while the first key is still held down). Staccato      |\n|                      | detached notes strike cleanly with zero pitch sliding.         |\n+----------------------+----------------------------------------------------------------+</pre>"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">Legato Playing Example:\nKey C2 Held:   [====================]\nKey G2 Struck:               [====================]\nPitch:         C2 -----------&gt; GLIDES UP TO G2 (Because notes overlapped!)\n\nStaccato Playing Example:\nKey C2 Struck: [========] (Released)\nKey G2 Struck:            (Gap) [========]\nPitch:         C2               G2 (Instant jump with ZERO glide!)</pre>"},{"type":"prose","html":"<strong>Production Standard:</strong> Use <strong>Legato Glide (Mono Legato)</strong> for 808 basses and solo leads. It allows the performer to play tight, punchy rhythmic patterns with staccato notes and introduce expressive slides simply by holding down a key across a transition."},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Sound-Design-Beginner-Knowledgebase.md</em>, §5","<em>Ableton Live 12 Reference Manual</em>, Chapter 23 (Drift / Analog Mode Controls)"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-6-1-8","title":"6.1.8 — Finding Voice and Glide Controls Across Studio Synths","blocks":[{"type":"step","title":"6.1.8 — Finding Voice and Glide Controls Across Studio Synths","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+---------------+-----------------------------------------------------------------------+\n| Engine        | Voice &amp; Glide Section Navigation                                      |\n+---------------+-----------------------------------------------------------------------+\n| **`Drift`**   | Right-side Mode panel: **Voice Mode** (Poly, Mono, Stereo, Unison).   |\n|               | **Glide** toggle and Time slider located directly in the Mode box.    |\n+---------------+-----------------------------------------------------------------------+\n| **`Analog`**  | Central sub-panel under global shell: Click **VCA** / Master display. |\n|               | Select **Mono / Poly / Unison**, Unison Detune, and Glide / Legato.   |\n+---------------+-----------------------------------------------------------------------+\n| **`Operator`**| Global Shell (bottom-right block): Select **Voices** ($1 - 32$). Set  |\n|               | **Glide** toggle and Glide Time directly in the central display.      |\n+---------------+-----------------------------------------------------------------------+\n| **`Vital`**   | Bottom-right corner: **VOICING** panel. Set Polyphony count,          |\n|               | **Portamento / Glide Time**, and toggle **Legato** mode.              |\n+---------------+-----------------------------------------------------------------------+\n| **`Surge XT`**| Top-center Scene header: **Play Mode** (Poly, Mono, Mono (ST), Mono (FP)|\n|               | / Latch). **Portamento** time and Legato curve sliders adjacent.      |\n+---------------+-----------------------------------------------------------------------+</pre>"},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Ableton Live 12 Reference Manual</em>, Chapter 23","<em>Vital User Manual</em>, Section 2","<em>Surge XT User Manual</em>, Section 2"],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"sounddesign-m-6-2-2","code":"6.2","title":"Signal Flow Literacy","blurb":"- Trace and diagram the universal subtractive signal path from generator to master track output. - Compare and configure Serial Routing (cascading processors) and Parallel Routing (split independent paths).","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"sounddesign-l-o-17","title":"Section overview","blocks":[{"type":"step","title":"Learning Objectives","blocks":[{"type":"list","items":["Trace and diagram the universal subtractive signal path from generator to master track output.","Compare and configure <strong>Serial Routing</strong> (cascading processors) and <strong>Parallel Routing</strong> (split independent paths).","Master dual-oscillator, dual-filter, and dual-amplifier signal routing inside <code>Analog</code> and <code>Surge XT</code>.","Differentiate <strong>Control-Rate Modulation</strong> (&lt;20 Hz) from <strong>Audio-Rate Modulation</strong> (20 Hz - 20 kHz).","Execute internal gain staging across mixer, filter drive, and VCA stages to prevent unwanted digital clipping.","Decode unfamiliar software synthesizer GUIs as functional schematic signal maps."],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-6-2-1","title":"6.2.1 — The Universal Signal Path","blocks":[{"type":"step","title":"6.2.1 — The Universal Signal Path","blocks":[{"type":"prose","html":"Every synthesizer architecture—from a single-oscillator analog synth to a modular digital workstation—is structured around the <strong>Universal Subtractive Signal Path</strong>:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+---------------------------------------------------------------------------------------------------+\n|                                 THE UNIVERSAL SIGNAL PATH                                         |\n+---------------------------------------------------------------------------------------------------+\n|                                                                                                   |\n|  [ OSCILLATOR 1 ] ---+                                                                            |\n|                      |                                                                            |\n|  [ OSCILLATOR 2 ] ---+===&gt; [ MIXER / DRIVE ] ===&gt; [ FILTER (VCF) ] ===&gt; [ AMPLIFIER (VCA) ] ===&gt;  |\n|                      |                                   ^                      ^                 |\n|  [ NOISE GEN    ] ---+                                   |                      |                 |\n|                                                    [ FILTER ENV ]          [ AMP ENV ]            |\n|                                                          ^                      ^                 |\n|                                                          |                      |                 |\n|                                                 [ MODULATION MATRIX (LFOs / Macros / MIDI) ]      |\n|                                                                                                   |\n+---------------------------------------------------------------------------------------------------+\n                                                                                     |\n                                                                                     v\n                                                                          [ INTERNAL FX / BUS ]\n                                                                                     |\n                                                                                     v\n                                                                          [ ABLETON TRACK FX ]</pre>"},{"type":"list","items":["<strong>Source Generation:</strong> Oscillators and noise generators produce raw electrical/algorithmic waveforms.","<strong>Mixer / Summing Stage:</strong> Individual source levels are balanced and summed into a composite signal.","<strong>Spectral Shaping (VCF):</strong> Filters remove, sculpt, and accentuate harmonic content.","<strong>Loudness Shaping (VCA):</strong> The amplifier envelope applies dynamic amplitude contouring.","<strong>Finishing Processing:</strong> Internal effects (chorus, delay, distortion) and external track insert effects finalize spatial and dynamic positioning."],"ordered":true},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Ultimate Sound Design: Mastering Sound Design</em>, Section 6.4 (Universal Signal Architecture)","<em>Sound-Design-Beginner-Knowledgebase.md</em>, §2.4"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-6-2-2","title":"6.2.2 — Serial vs. Parallel Routing","blocks":[{"type":"step","title":"6.2.2 — Serial vs. Parallel Routing","blocks":[{"type":"prose","html":"When an instrument features multiple filters, processors, or effect chains, they can be connected in two fundamental configurations:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">SERIAL ROUTING (Cascading Processing):\n[ AUDIO SOURCE ] ===&gt; [ FILTER 1 (Low-Pass) ] ===&gt; [ FILTER 2 (High-Pass) ] ===&gt; [ OUTPUT ]\n                      (Passes Lows/Mids)            (Removes Sub Rumble)\n(The output of Filter 1 becomes the direct input of Filter 2)\n\nPARALLEL ROUTING (Independent Dual Paths):\n                      +===&gt; [ FILTER 1 (Warm Low-Pass)  ] ===+\n                      |                                       |\n[ AUDIO SOURCE ] ====&gt;+                                       +===&gt; [ SUMMING MIXER ] ===&gt; [ OUTPUT ]\n                      |                                       |\n                      +===&gt; [ FILTER 2 (Resonant High-Pass) ]+\n(The audio source splits equally into both filters; their outputs are summed together at the end)</pre>"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+------------------+----------------------------------+-----------------------------------------+\n| Routing Schema   | Signal Behavior                  | Common Production Application           |\n+------------------+----------------------------------+-----------------------------------------+\n| **Serial**       | Each stage further modifies the  | Low-pass tone filtering followed by a   |\n|                  | previous stage's result.         | high-pass filter to clean up low rumble.|\n+------------------+----------------------------------+-----------------------------------------+\n| **Parallel**     | Two independent timbral layers   | Mixing a clean, undistorted low sub     |\n|                  | are processed side-by-side.      | alongside an aggressively filtered mid. |\n+------------------+----------------------------------+-----------------------------------------+</pre>"},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Ableton Live 12 Reference Manual</em>, Chapter 23 (Analog Filter Routing)","<em>Surge XT User Manual</em>, Section 4 (Dual Filter Configuration)"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-6-2-3","title":"6.2.3 — Dual-Path Signal Routing in Ableton Analog","blocks":[{"type":"step","title":"6.2.3 — Dual-Path Signal Routing in Ableton Analog","blocks":[{"type":"prose","html":"<code>Analog</code> provides a classic hardware-modeled dual-path signal routing architecture:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">ANALOG DUAL-PATH SCHEMATIC:\n[ OSC 1 ] --(F1/F2 Balance)--&gt; [ FILTER 1 ] ===&gt; [ AMP 1 ] --+\n                                  |                           |\n                               (F2 Link: Serial)              +===&gt; [ MASTER OUT ]\n                                  v                           |\n[ OSC 2 ] --(F1/F2 Balance)--&gt; [ FILTER 2 ] ===&gt; [ AMP 2 ] --+</pre>"}]},{"type":"step","title":"Routing Capabilities:","blocks":[{"type":"list","items":["<strong>Oscillator Routing (<code>F1/F2</code>):</strong> Each oscillator can send 100% of its output to Filter 1, 100% to Filter 2, or split 50/50 across both.","<strong>Filter-to-Filter Link (<code>To F2</code>):</strong> Activating <code>To F2</code> routes the output of Filter 1 directly into the input of Filter 2 (converting parallel mode into serial mode).","<strong>Independent Envelopes:</strong> Filter 1 and Filter 2 have completely independent ADSR envelopes; Amp 1 and Amp 2 have completely independent volume contours."],"ordered":false},{"type":"prose","html":"This enables you to design a punchy, short-decay plucked transient on Osc 1/Filter 1 while Osc 2/Filter 2 outputs a sustained, warm pad body on the same single MIDI track."},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Ableton Live 12 Reference Manual</em>, Chapter 23 (Analog Architecture &amp; Routing)"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-6-2-4","title":"6.2.4 — Pre vs. Post Effects: Inside the Synth vs. On the Track","blocks":[{"type":"step","title":"6.2.4 — Pre vs. Post Effects: Inside the Synth vs. On the Track","blocks":[{"type":"prose","html":"Sound designers must choose whether to apply distortion, chorus, and delay <strong>inside the synth's internal effects module</strong> or <strong>as discrete audio effects on the Ableton track device chain</strong>:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+--------------------------+--------------------------------------------------------------------+\n| Processing Location      | Acoustic / Engineering Advantages                                  |\n+--------------------------+--------------------------------------------------------------------+\n| **Inside Synth Engine**  | - **Per-Voice Polyphonic Processing:** Some internal effects can   |\n| (`Vital`, `Surge XT`)    |   apply distortion/waveshaping *per polyphonic voice* before sum.  |\n|                          | - **Modulation Integration:** Internal LFOs/Envelopes can modulate |\n|                          |   effect parameters (e.g., LFO modulating internal Reverb Mix).    |\n+--------------------------+--------------------------------------------------------------------+\n| **On Ableton Track**     | - **Modular Flexibility:** Full visual control with `EQ Eight`,    |\n| (Insert Device Chain)    |   `Glue Compressor`, `Saturator`, and `Auto Filter`.               |\n|                          | - **Precision Automation:** Direct arrangement lane automation.    |\n|                          | - **Standardization:** Consistent finishing chains across engines. |\n+--------------------------+--------------------------------------------------------------------+</pre>"},{"type":"prose","html":"<strong>Standard Studio Practice:</strong> Use internal synth effects for core timbral synthesis (e.g., internal waveshaper, unison chorus, spectral distortion). Use Ableton track effects for mixing balance, surgical EQ carving, sidechain ducking, and spatial positioning."},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Sound-Design-Beginner-Knowledgebase.md</em>, §8 &amp; §13"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-6-2-5","title":"6.2.5 — Audio-Rate vs. Control-Rate Modulation","blocks":[{"type":"step","title":"6.2.5 — Audio-Rate vs. Control-Rate Modulation","blocks":[{"type":"prose","html":"Understanding modulation bandwidth separates basic synthesizer operation from advanced FM and waveshaping:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+----------------------------------+----------------------------------+-------------------------+\n| Modulation Domain                | Frequency Band                   | Acoustic Manifestation  |\n+----------------------------------+----------------------------------+-------------------------+\n| **Control-Rate Modulation (LFO)**| $0.01\\text{ Hz} - 20\\text{ Hz}$  | Cyclical temporal       |\n|                                  | (Below audible threshold)        | movement (Vibrato, Wub).|\n+----------------------------------+----------------------------------+-------------------------+\n| **Audio-Rate Modulation (FM/AM)**| $20\\text{ Hz} - 20\\text{ kHz}$   | New harmonic sidebands, |\n|                                  | (Inside audible spectrum)        | metallic timbres, grit. |\n+----------------------------------+----------------------------------+-------------------------+</pre>"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[ LFO at 2 Hz ]   ===Modulates Pitch===&gt; Smooth rhythmic pitch waver (Vibrato).\n[ LFO at 200 Hz ] ===Modulates Pitch===&gt; The wavering happens so fast that the human ear no longer\n                                         hears movement; it hears a completely NEW METALLIC TIMBRE\n                                         (Frequency Modulation / FM Synthesis).</pre>"},{"type":"prose","html":"<em>(Audio-rate modulation is explored in full depth in Module 8: Operator).</em>"},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Ultimate Sound Design: Mastering Sound Design</em>, Section 6.5 (Audio-Rate vs Control-Rate)"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-6-2-6","title":"6.2.6 — Gain Staging Through the Internal Chain","blocks":[{"type":"step","title":"6.2.6 — Gain Staging Through the Internal Chain","blocks":[{"type":"prose","html":"Uncontrolled internal gain staging leads to harsh, unmusical digital clipping and ruined dynamics:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[ OSCILLATORS ] ======&gt; [ PRE-FILTER MIXER ] ======&gt; [ FILTER STAGE ] ======&gt; [ VCA AMP ] ======&gt; [ TRACK OUT ]\n  (0 dB Peak)             (+6 dB Hot Boost)            (Resonance +9 dB)       (Master Out)          (CLIPPING!)\n                               |                               |\n                               v                               v\n                     Pre-Filter Distortion           Filter Output Overload</pre>"}]},{"type":"step","title":"The Four Internal Gain Rules:","blocks":[{"type":"list","items":["<strong>Multi-Oscillator Headroom:</strong> Stacking three oscillators at 100% volume sums to +9.5 dBFS of gain, overloading the mixer stage. Back each oscillator down to ≈ 70% (-3 dB) to preserve headroom.","<strong>Resonance Compensation:</strong> High filter resonance generates massive narrow-band amplitude spikes (up to +18 dB). Lower the synth's master volume slider when working with extreme resonance.","<strong>Drive Management:</strong> If you increase pre-filter Drive, reduce the master VCA level proportionally to maintain unity gain.","<strong>Meter Verification:</strong> Ensure the Ableton track meter never exceeds -6.0 dBFS during design tracking."],"ordered":true},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Sound-Design-Beginner-Knowledgebase.md</em>, §10 (Gain Staging)","<em>Ableton Live 12 Reference Manual</em>, Chapter 23"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-6-2-7","title":"6.2.7 — Visual Signal Flow Diagramming Drill","blocks":[{"type":"step","title":"6.2.7 — Visual Signal Flow Diagramming Drill","blocks":[{"type":"prose","html":"When analyzing or designing a patch, map out the five-point schematic on paper or in your head:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                       PATCH SCHEMATIC TEMPLATE                                |\n+-------------------------------------------------------------------------------+\n| 1. GENERATORS:  Osc 1 (Saw, 0 st) + Osc 2 (Square, -12 st, Detune +8c)        |\n| 2. MIXER:       Osc 1 @ 75%, Osc 2 @ 50%, Noise @ 10%                         |\n| 3. FILTER:      LPF 24 dB/oct, Cutoff @ 350 Hz, Res @ 30%, Keytrack @ 100%   |\n| 4. ENVELOPES:   AEG (A: 0ms, D: 250ms, S: 40%, R: 30ms)                       |\n|                 FEG (A: 0ms, D: 180ms, S: 0%,  R: 30ms, Depth: +65%)          |\n| 5. MODULATION:  LFO 1 (1/8th Triplet, Retrigger) -&gt; Filter Cutoff (+20%)      |\n| 6. FINISH:      Saturator (Soft Clip, +3 dB Drive) -&gt; EQ Eight (HPF @ 35 Hz)  |\n+-------------------------------------------------------------------------------+</pre>"},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Ultimate Sound Design: Mastering Sound Design</em>, Section 6.6"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-6-2-8","title":"6.2.8 — Reading a Synth UI as a Functional Signal Map","blocks":[{"type":"step","title":"6.2.8 — Reading a Synth UI as a Functional Signal Map","blocks":[{"type":"prose","html":"Do not look at a complex software synthesizer (<code>Surge XT</code>, <code>Vital</code>, <code>Operator</code>) as a confusing wall of knobs. Decode the interface by identifying the functional blocks in signal-flow order:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[ 1. GENERATORS ]  ===&gt;  [ 2. MIXER ]  ===&gt;  [ 3. FILTERS ]  ===&gt;  [ 4. AMPLIFIER ]  ===&gt;  [ 5. FX ]\n  (Look for Osc /         (Look for Vol /      (Look for Cutoff /   (Look for ADSR /        (Look for Reverb /\n   Wavetable frames)       Level sliders)       Res / Slope)         VCA sliders)            Distortion tabs)\n         ^                                           ^                     ^\n         |                                           |                     |\n         +------------------- [ 6. MODULATION ENGINE ] --------------------+\n                                (Look for LFOs, Matrix, Envelopes)</pre>"},{"type":"prose","html":"No matter how futuristic or stylized a plugin GUI appears, every subtractive synthesizer in existence obeys this universal architectural map."},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Sound-Design-Beginner-Knowledgebase.md</em>, §6 &amp; §7"],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"sounddesign-m-6-3-3","code":"6.3","title":"Multi-Oscillator Thickness","blurb":"- Calculate and control micro-tuning offsets (Cents) to dictate the speed of Phase Beating between dual oscillators. - Layer multi-octave (8' + 16') and interval (+7 semitones) oscillators to construct dense harmonic stabs and massive lead ","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"sounddesign-l-o-18","title":"Section overview","blocks":[{"type":"step","title":"Learning Objectives","blocks":[{"type":"list","items":["Calculate and control <strong>micro-tuning offsets</strong> (Cents) to dictate the speed of <strong>Phase Beating</strong> between dual oscillators.","Layer multi-octave (8' + 16') and interval (+7 semitones) oscillators to construct dense harmonic stabs and massive lead foundations.","Combine disparate geometric waveforms (<strong>Sawtooth + Square</strong>) to merge high-frequency bite with low-mid hollow body.","Integrate dedicated <strong>Sub-Oscillators</strong> to anchor monophonic basslines with clean, pitch-stable fundamentals.","Program <strong>Oscillator Hard Sync</strong> to synthesize aggressive, tearing vocal sync leads.","Calibrate <strong>Oscillator Phase Reset</strong> vs. <strong>Random Phase</strong> to balance transient punch against spatial width."],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-6-3-1","title":"6.3.1 — Why One Oscillator is Often Thin","blocks":[{"type":"step","title":"6.3.1 — Why One Oscillator is Often Thin","blocks":[{"type":"prose","html":"A single initialized oscillator (e.g., one sawtooth wave running through an open filter) generates a mathematically static, repetitive waveform."},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">Single Oscillator:\nAmplitude\n  1.0 |    /|    /|    /|\n  0.0 |--+--+--+--+--+--+--&gt; Time  [Static, clinical, two-dimensional tone]\n -1.0 | /   | /   | /   |</pre>"},{"type":"prose","html":"While clean and focused (ideal for sub-basses and pure melodic plucks), a single oscillator lacks the dynamic microscopic pitch fluctuations, phase cancellations, and stereo movement present in real-world acoustic instruments (where multiple violins or piano strings vibrate together)."},{"type":"prose","html":"To create thickness, width, and acoustic life, sound designers layer multiple oscillators with intentional pitch, octave, and waveform offsets."},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Ultimate Sound Design: Mastering Sound Design</em>, Section 6.7 (Multi-Oscillator Staging)","<em>PML Synthesis – 1 – Oscillator</em>, Chapter 5"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-6-3-2","title":"6.3.2 — Two Oscillators: Detuning Math and Beating Speed","blocks":[{"type":"step","title":"6.3.2 — Two Oscillators: Detuning Math and Beating Speed","blocks":[{"type":"prose","html":"When two oscillators play the exact same nominal pitch but are offset by a small micro-tuning interval in <strong>Cents</strong> (± 1 to ± 30 cents), their phase relationship continuously cycles between constructive and destructive interference."},{"type":"prose","html":"Beating Frequency (f_beat) = |f_osc1 - f_osc2|"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+------------------+-----------------------+----------------------------------------------------+\n| Detune Amount    | Beating Speed         | Acoustic Character &amp; Application                   |\n+------------------+-----------------------+----------------------------------------------------+\n| **$\\pm 2 - 4\\text{ cents}$**| Slow, gentle shimmer | Subtle vintage analog drift, warm acoustic pads.   |\n+------------------+-----------------------+----------------------------------------------------+\n| **$\\pm 6 - 12\\text{ cents}$**| Moderate pulsing    | Classic Reese bass movement, rich 80s synth leads. |\n+------------------+-----------------------+----------------------------------------------------+\n| **$\\pm 15 - 30\\text{ cents}$**| Fast, aggressive flutter| Heavy trance supersaws, thick modern EDM chords. |\n+------------------+-----------------------+----------------------------------------------------+</pre>"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">Acoustic Phase Beating Waveform:\n  /\\  /\\  /\\                                /\\  /\\  /\\\n /  \\/  \\/  \\______________________________/  \\/  \\/  \\\n|&lt;-- Constructive --&gt;|&lt;--- Destructive ---&gt;|&lt;-- Constructive --&gt;|\n     (Loud Peak)      (Phase Cancellation)      (Loud Peak)</pre>"},{"type":"prose","html":"<strong>Tuning Practice:</strong> Offset Osc 1 by +7 cents and Osc 2 by -7 cents. This maintains perfect center pitch balance on average while creating symmetrical phase movement."},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>PML Synthesis – 1 – Oscillator</em>, Chapter 6 (Detuning &amp; Beating)","<em>Sound-Design-Beginner-Knowledgebase.md</em>, §2.1 &amp; §5"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-6-3-3","title":"6.3.3 — Octave Layering: 8' + 16' (Body + Sizzle)","blocks":[{"type":"step","title":"6.3.3 — Octave Layering: 8' + 16' (Body + Sizzle)","blocks":[{"type":"prose","html":"A foundational synthesis technique is layering two identical waveforms separated by exactly <strong>one musical octave</strong> (12 semitones or 8' + 16' footage):"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[ OSCILLATOR 1: Sawtooth @ 8' (Standard Pitch C2 = 130 Hz) ] ===&gt; Provides Bright Mid-High Sizzle\n                               +\n[ OSCILLATOR 2: Sawtooth @ 16' (-1 Octave C1 = 65 Hz)      ] ===&gt; Provides Heavy Low-Mid Body\n                               |\n                               v\n                     [ MASSIVE FULL-SPECTRUM BASS FOUNDATION ]</pre>"},{"type":"list","items":["<strong>Oscillator 1 (8'):</strong> Drives through the filter to supply cutting presence, harmonics, and bite in the 1 kHz - 8 kHz region.","<strong>Oscillator 2 (16'):</strong> Provides solid, foundational acoustic weight in the 60 Hz - 250 Hz region."],"ordered":false},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Ultimate Sound Design: Mastering Sound Design</em>, Section 6.8 (Octave Stacks)","<em>Sound-Design-Beginner-Knowledgebase.md</em>, §2.1"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-6-3-4","title":"6.3.4 — Interval Layering: 5ths (+7 Semitones) for Chord Stabs","blocks":[{"type":"step","title":"6.3.4 — Interval Layering: 5ths (+7 Semitones) for Chord Stabs","blocks":[{"type":"prose","html":"Setting Oscillator 2 to an interval of <strong>+7 semitones (a Perfect 5th)</strong> above Oscillator 1 creates a multi-tonal composite waveform on every single keypress:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[ OSC 1 (Root Pitch C3 = 0 st) ] + [ OSC 2 (Perfect 5th G3 = +7 st) ] ===&gt; [ PARALLEL 5th STAB ]</pre>"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+------------------+-----------------------+----------------------------------------------------+\n| Interval Offset  | Semitones Transposed  | Timbral Result &amp; Application                       |\n+------------------+-----------------------+----------------------------------------------------+\n| **Minor 3rd**    | $+3\\text{ semitones}$ | Dark, melancholic techno and dub chord stabs.      |\n+------------------+-----------------------+----------------------------------------------------+\n| **Major 3rd**    | $+4\\text{ semitones}$ | Bright, euphoric classic house organ stabs.        |\n+------------------+-----------------------+----------------------------------------------------+\n| **Perfect 5th**  | $+7\\text{ semitones}$ | Classic rock/electronic power chord; heavy stabs.  |\n+------------------+-----------------------+----------------------------------------------------+</pre>"},{"type":"prose","html":"Playing a monophonic melody with an oscillator tuned to a 5th gives the acoustic illusion of a full chord progression moving in parallel."},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Ultimate Sound Design: Mastering Sound Design</em>, Section 6.9 (Harmonic Intervals)"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-6-3-5","title":"6.3.5 — Waveform Mixing: Saw + Square","blocks":[{"type":"step","title":"6.3.5 — Waveform Mixing: Saw + Square","blocks":[{"type":"prose","html":"Rather than layering two identical waveforms, combining different geometric waveforms yields complex hybrid timbres that cannot be generated by a single oscillator:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[ OSCILLATOR 1: Sawtooth ]  ===&gt; (Even + Odd Harmonics: Bright, brassy buzz)\n            +\n[ OSCILLATOR 2: Square ]    ===&gt; (Odd Harmonics Only: Hollow, woody, nasal punch)\n            |\n            v\n[ COMPOSITE HYBRID TIMBRE ] ===&gt; Rich, heavy low-end body with a crisp cutting edge.</pre>"},{"type":"list","items":["<strong>Mix Ratio:</strong> Set Sawtooth at 80% volume and Square at 50% volume. The square wave fills out the low-mid frequencies (200-500 Hz) with hollow weight, while the sawtooth supplies shimmering top-end clarity."],"ordered":false},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>PML Synthesis – 1 – Oscillator</em>, Chapter 7 (Waveform Summing)"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-6-3-6","title":"6.3.6 — The Sub-Oscillator: Anchoring the Fundamental","blocks":[{"type":"step","title":"6.3.6 — The Sub-Oscillator: Anchoring the Fundamental","blocks":[{"type":"prose","html":"A <strong>Sub-Oscillator</strong> is an auxiliary generator dedicated exclusively to producing a clean, solid, unmodulated low-frequency fundamental tuned <strong>one or two octaves below Oscillator 1</strong> (-12 or -24 st)."},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[ OSC 1: Detuned Stereo Sawtooths ] ===&gt; [ Heavy Stereo Chorus / Phaser ] ===&gt; (Mid/High Layer)\n                                              +\n[ SUB-OSC: Pure Sine / Triangle   ] ===&gt; [ Direct Clean Mono Path       ] ===&gt; (Solid Sub Layer: 40 Hz)\n                                              |\n                                              v\n                              [ CLUB-READY MONO-COMPATIBLE BASS ]</pre>"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+------------------+--------------------------------------------------------------------+\n| Sub-Osc Waveform | Acoustic Utility                                                   |\n+------------------+--------------------------------------------------------------------+\n| **Pure Sine**    | Cleanest possible club low-end ($30-60\\text{ Hz}$); maximum headroom|\n+------------------+--------------------------------------------------------------------+\n| **Triangle**     | Soft harmonic presence; audible on smaller laptop/phone speakers.  |\n+------------------+--------------------------------------------------------------------+\n| **Square**       | Aggressive, hollow grit; cuts through dense rock and drum &amp; bass.  |\n+------------------+--------------------------------------------------------------------+</pre>"},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Sound-Design-Beginner-Knowledgebase.md</em>, §2.1 &amp; §6","<em>Dubstep-Production-Beginner-Live12-Launchkey.md</em>, §6.1"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-6-3-7","title":"6.3.7 — Hard Sync: Tearing Lead Synthesis","blocks":[{"type":"step","title":"6.3.7 — Hard Sync: Tearing Lead Synthesis","blocks":[{"type":"prose","html":"<strong>Oscillator Hard Sync</strong> is a synthesis mechanism where a secondary oscillator (the <strong>Slave</strong>) has its waveform phase <strong>force-reset to 0^ every time a primary oscillator (the Master) completes one full cycle</strong>."},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[ MASTER OSC (Tuned to Fixed Pitch C2) ] ===(Phase Reset Trigger)===&gt; [ SLAVE OSC (Pitch Modulated) ]\n                                                                                |\n                                                                                v\n                                                              [ Hard-Edged Geometric Waveform ]\n                                                                                |\n                                                                                v\n                                                              [ Screaming, Tearing Harmonic Lead ]</pre>"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">Slave Waveform Reset Under Hard Sync:\nAmplitude\n  1.0 |    /|  /|    /|  /|\n  0.0 |--+--+-+--+--+--+-+--&gt; Time  [Forced resets create new, sharp harmonic corners]\n -1.0 | /   |/   | /   |/   |\n        ^        ^\n    (Reset 1) (Reset 2: Forced by Master Osc Cycle)</pre>"}]},{"type":"step","title":"Acoustic Result:","blocks":[{"type":"prose","html":"When you sweep the pitch of the Slave oscillator upward using an envelope or pitch bend wheel, the pitch does <em>not</em> rise musically; instead, the sound emits a screaming, tearing, metallic vocal timbre (the legendary synth lead sound of The Cars, Daft Punk, and modern electro)."},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Ultimate Sound Design: Mastering Sound Design</em>, Section 6.10 (Oscillator Sync)","<em>Surge XT User Manual</em>, Section 2 (Classic Oscillator Sync)"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-6-3-8","title":"6.3.8 — Phase Reset vs. Random Phase","blocks":[{"type":"step","title":"6.3.8 — Phase Reset vs. Random Phase","blocks":[{"type":"prose","html":"In digital synthesizers (<code>Vital</code>, <code>Surge XT</code>), you can configure how each oscillator initializes its waveform phase upon a new MIDI Note-On event:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+----------------------+----------------------------------+-------------------------------------+\n| Phase Mode           | Phase Behavior on Keypress       | Sound Design Application            |\n+----------------------+----------------------------------+-------------------------------------+\n| **Phase Reset ($0^\\circ$)**| The wave starts at precisely $0^\\circ$| **Mandatory for Kicks &amp; Sub Bass.** |\n| **(Retrigger On)**   | on every single key strike.      | Guarantees identical transient punch|\n|                      |                                  | and zero low-end phase smearing.    |\n+----------------------+----------------------------------+-------------------------------------+\n| **Random Phase**     | The wave starts at a completely  | **Mandatory for Pads &amp; Supersaws.** |\n| **(Free-Running)**   | random point in its cycle ($0-360^\\circ$)| Prevents artificial flanging clicks |\n|                      | on every note.                   | on note onset; maximizes width.     |\n+----------------------+----------------------------------+-------------------------------------+</pre>"},{"type":"prose","html":"<strong>The Phase Law:</strong>"},{"type":"list","items":["Sub-bass &amp; Drum transients → <strong>Phase Reset ON (0°)</strong> (Zero variation, maximum punch).","Supersaws, Pads &amp; Unison leads → <strong>Random Phase ON (100%)</strong> (Smooth acoustic onset, zero flanging)."],"ordered":false},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Vital User Manual</em>, Section 2 (Oscillator Phase &amp; Random Phase)","<em>Sound-Design-Beginner-Knowledgebase.md</em>, §5"],"ordered":false}]}],"minutes":8}],"exercises":[]}]};
